int y = 25;

if (x > 10) {
 cout << "x is greater than 10\n";

 // Nested if
 if (y > 20) {
 cout << "y is also greater than 20\n";
 }
}

Result:

x is greater than 10

y is also greater than 20

Try it Yourself »

