};

// 
 Derived 
 class (child)
class MyChild: public MyClass {
};

// Derived class 
 (grandchild) 
class MyGrandChild: public MyChild {
};

int main() {

 MyGrandChild myObj;

 myObj.myFunction();

 return 0;
}

