// Add elements to the queue
cars.push("Volvo");
cars.push("BMW");

 cars.push("Ford");
cars.push("Mazda");

// Remove the 
 front 
 element (Volvo)
cars.pop();

// Access the front 
 element (Now BMW)

 cout << cars.front();

Try it Yourself »

